pub fn release(version: &str) -> Option<&'static GeneratedRelease<'static>> {
    RELEASES.iter().find(|release| release.version == version)
}

pub fn block(version: &str, id: &str) -> Option<&'static GeneratedBlock<'static>> {
    release(version)?.blocks.iter().find(|block| block.id == id)
}

pub fn source_shape_boxes(version: &str, id: &str) -> Option<&'static [GeneratedShapeBox]> {
    Some(block(version, id)?.source_shape_boxes)
}

pub fn method_shape_boxes(version: &str, id: &str, kind: &str) -> Option<&'static [GeneratedShapeBox]> {
    let block = block(version, id)?;
    match kind {
        "collision" => block.has_collision_shape_method.then_some(block.collision_shape_boxes),
        "outline" => block.has_outline_shape_method.then_some(block.outline_shape_boxes),
        "interaction" => block.has_interaction_shape_method.then_some(block.interaction_shape_boxes),
        _ => None,
    }
}

pub fn exact_method_shape_boxes(version: &str, id: &str, kind: &str) -> Option<&'static [GeneratedShapeBox]> {
    let block = block(version, id)?;
    match kind {
        "collision" if block.has_collision_shape_method && !block.collision_shape_state_dependent => Some(block.collision_shape_boxes),
        "outline" if block.has_outline_shape_method && !block.outline_shape_state_dependent => Some(block.outline_shape_boxes),
        "interaction" if block.has_interaction_shape_method && !block.interaction_shape_state_dependent => Some(block.interaction_shape_boxes),
        _ => None,
    }
}

