pub fn method_shape_provenance(version: &str, id: &str, kind: &str) -> Option<GeneratedShapeProvenance<'static>> {
    let block = block(version, id)?;
    match kind {
        "collision" => Some(GeneratedShapeProvenance { source_sha256: block.collision_shape_sha256, has_method: block.has_collision_shape_method, state_dependent: block.collision_shape_state_dependent, property_dependencies: block.collision_shape_property_dependencies, candidate_box_count: block.collision_shape_boxes.len() }),
        "outline" => Some(GeneratedShapeProvenance { source_sha256: block.outline_shape_sha256, has_method: block.has_outline_shape_method, state_dependent: block.outline_shape_state_dependent, property_dependencies: block.outline_shape_property_dependencies, candidate_box_count: block.outline_shape_boxes.len() }),
        "interaction" => Some(GeneratedShapeProvenance { source_sha256: block.interaction_shape_sha256, has_method: block.has_interaction_shape_method, state_dependent: block.interaction_shape_state_dependent, property_dependencies: block.interaction_shape_property_dependencies, candidate_box_count: block.interaction_shape_boxes.len() }),
        _ => None,
    }
}

pub fn state_index(version: &str, id: &str, values: &[(&str, &str)]) -> Option<usize> {
    let block = block(version, id)?;
    if block.properties.iter().any(|property| property.values.is_empty()) { return None; }
    if values.len() != block.properties.len() { return None; }
    if values.iter().any(|(name, _)| block.properties.iter().filter(|property| property.name == *name).count() != 1) { return None; }
    if block.properties.iter().any(|property| values.iter().filter(|(name, _)| *name == property.name).count() != 1) { return None; }
    let mut properties: Vec<&GeneratedProperty<'static>> = block.properties.iter().collect();
    properties.sort_by_key(|property| property.name);
    let mut index = 0usize;
    let mut stride = 1usize;
    for property in properties.iter().rev() {
        let value = values.iter().find(|(name, _)| *name == property.name)?.1;
        let position = property.values.iter().position(|candidate| *candidate == value)?;
        index = index.checked_add(position.checked_mul(stride)?)?;
        stride = stride.checked_mul(property.values.len())?;
    }
    (values.len() == block.properties.len()).then_some(index)
}

pub fn fluid(version: &str, id: &str) -> Option<&'static GeneratedFluid<'static>> {
    release(version)?.fluids.iter().find(|fluid| fluid.id == id)
}

pub fn fluid_state_index(version: &str, id: &str, values: &[(&str, &str)]) -> Option<usize> {
    let fluid = fluid(version, id)?;
    if fluid.state_count == 0 || values.len() != fluid.property_names.len() { return None; }
    if fluid.property_names.iter().any(|property_name| values.iter().filter(|(name, _)| *name == *property_name).count() != 1) { return None; }
    if values.iter().any(|(name, _)| fluid.property_names.iter().filter(|property_name| **property_name == *name).count() != 1) { return None; }
    let mut positions: Vec<(&str, usize, usize)> = Vec::with_capacity(fluid.property_names.len());
    for property_name in fluid.property_names {
        let value = values.iter().find(|(name, _)| *name == *property_name)?.1;
        let property_index = fluid.property_names.iter().position(|candidate| *candidate == *property_name)?;
        let domain = *fluid.property_domains.get(property_index)?;
        let position = domain.iter().position(|candidate| *candidate == value)?;
        let domain_len = domain.len();
        positions.push((*property_name, position, domain_len));
    }
    positions.sort_by_key(|(name, _, _)| *name);
    let mut index = 0usize;
    let mut stride = 1usize;
    for (_, position, domain_len) in positions.iter().rev() {
        index = index.checked_add(position.checked_mul(stride)?)?;
        stride = stride.checked_mul(*domain_len)?;
    }
    (index < fluid.state_count).then_some(index)
}

pub fn fluid_tag(version: &str, id: &str) -> Option<&'static GeneratedFluidTag<'static>> {
    release(version)?.fluid_tags.iter().find(|tag| tag.id == id)
}

pub fn block_tag(version: &str, id: &str) -> Option<&'static GeneratedBlockTag<'static>> {
    release(version)?.block_tags.iter().find(|tag| tag.id == id)
}

pub fn block_has_tag(version: &str, block: &str, tag: &str) -> bool {
    fn visit(release: &GeneratedRelease<'static>, block: &str, tag: &str, visited: &mut Vec<&'static str>) -> bool {
        if visited.contains(&tag) { return false; }
        let Some(definition) = release.block_tags.iter().find(|candidate| candidate.id == tag) else { return false; };
        if definition.blocks.iter().any(|candidate| *candidate == block) { return true; }
        visited.push(definition.id);
        let found = definition.includes.iter().any(|included| visit(release, block, included, visited));
        visited.pop();
        found
    }
    release(version).is_some_and(|release| visit(release, block, tag, &mut Vec::new()))
}

